/**
 * Creates a BVH closest point to point function using TSL Fn().
 *
 * This uses the TSL Fn() pattern which:
 * 1. Accesses storage buffers via .element() - generates NodeBuffer_XXX.value[i] syntax
 * 2. Avoids ptr<storage, ...> in function signatures
 * 3. Works on Safari/Firefox WebGPU
 *
 * @param {StorageBufferNode} bvhIndexBuffer - Storage buffer for triangle indices (uvec3)
 * @param {StorageBufferNode} bvhPositionBuffer - Storage buffer for vertex positions (vec3f)
 * @param {StorageBufferNode} bvhNodeBuffer - Storage buffer for BVH nodes (BVHNode struct)
 * @returns {Function} A TSL function that computes closest point to point
 */
export function createBVHClosestPointFn(bvhIndexBuffer: StorageBufferNode, bvhPositionBuffer: StorageBufferNode, bvhNodeBuffer: StorageBufferNode): Function;
export const bvhNodeBoundsStruct: any;
export const bvhNodeStruct: any;
/**
 * Computes the closest point on a triangle to a given point.
 * Returns vec4(closestPoint.xyz, unused).
 */
export const closestPointToTriangleWGSL: any;
/**
 * Computes the squared distance from a point to an AABB.
 */
export const distanceSqToBoundsWGSL: any;
